"""Complete tubulointerstitial/cystic chapter with ADPKD and acquired cysts."""
from create_tubulointerstitial import rows,q
from qbank_authoring import ref,finalize
PK=ref('KDIGO 2025 ADPKD Guideline','https://kdigo.org/wp-content/uploads/2025/01/KDIGO-2025-ADPKD-Guideline.pdf')
GP=ref('GeneReviews: Autosomal Dominant Polycystic Kidney Disease','https://www.ncbi.nlm.nih.gov/books/NBK1246/')
AC=ref('NIDDK: Acquired Cystic Kidney Disease','https://www.niddk.nih.gov/health-information/kidney-disease/acquired-cystic-kidney-disease')

q('Bilateral enlarged cystic kidneys, hypertension and liver cysts occur in several generations. Which diagnosis is favored?', 'Autosomal dominant polycystic kidney disease',[
 ('ADTKD-UMOD as the most characteristic imaging phenotype','It typically has bland-urine interstitial disease without this extensive enlargement.'),('Acquired cystic disease as the best inherited explanation','ACKD is associated with CKD rather than a dominant family syndrome.'),('Isolated simple cysts','The diffuse enlarged-kidney and family pattern is different.')],
 'Distribution, size and inheritance define the cystic phenotype', '**ADPKD is a systemic inherited cystic disorder.**', ['Kidney function can remain preserved despite substantial cyst burden.','Extrarenal manifestations affect care.'], '**Confirm using age- and context-appropriate criteria.**', ['Genetics can help uncertain cases.','Assess BP and progression risk early.'], [['Kidneys','Often enlarged and bilateral'],['Inheritance','Usually dominant'],['Extrarenal','Liver and other manifestations']], [PK,GP], 'clinical_scenario')
q('How do PKD1 and PKD2 generally compare?', 'PKD1-associated disease tends to have a more severe average renal course, with substantial individual variability',[
 ('PKD2 invariably causes childhood kidney failure','That reverses the usual population pattern.'),('Gene identity precisely predicts an individual’s failure date','Genotype is not deterministic.'),('Only PKD1 can cause an ADPKD phenotype','PKD2 and other genes can produce related disease.')],
 'Genotype contributes to risk rather than fixing destiny', '**Variant type and other modifiers influence the course.**', ['Truncating PKD1 variants often indicate higher average risk.','Family history and imaging add information.'], '**Use a complete risk assessment.**', ['Do not select therapy from gene name alone.','Counsel about uncertainty and inheritance.'], [['PKD1','Often higher average severity'],['PKD2','Often later course'],['Individual risk','Multiple modifiers']], [PK,GP])
q('Why are ultrasound diagnostic criteria for ADPKD age- and context-dependent?', 'Cyst number normally changes with age and assay sensitivity and genotype influence detection',[
 ('Any single cyst in any adult proves ADPKD','Simple cysts become common with age.'),('A negative scan in every young relative definitively excludes disease','Early disease can be less conspicuous.'),('Family history has no effect on interpretation','Pretest probability and validated criteria matter.')],
 'An imaging count needs a prior probability', '**Use validated criteria for the relevant at-risk population.**', ['MRI can clarify selected equivocal cases.','Potential living donors need a sufficiently reliable exclusion strategy.'], '**Avoid an unsupported binary label.**', ['Review age, family variant and imaging method.','Genetic testing can resolve important uncertainty.'], [['Age','Affects expected cyst burden'],['Family risk','Affects interpretation'],['Uncertainty','MRI/genetics may help']], [PK,GP])
q('Does no recognized family history exclude ADPKD?', 'No; de novo disease, mosaicism and unrecognized or mild familial disease can occur',[
 ('Yes, every case has a known affected parent','Family recognition is incomplete.'),('No, therefore all incidental cysts are ADPKD','The phenotype still needs assessment.'),('Only a normal eGFR can exclude the disease','Function may remain normal early.')],
 'A negative history is not a negative molecular test', '**Evaluate imaging distribution and associated features.**', ['Other cystic genetic disorders can mimic ADPKD.','Atypical cases may benefit from broader genetic testing.'], '**Use the diagnostic consequence to choose testing.**', ['Reproductive counseling and donor evaluation can justify precision.','Avoid overdiagnosing from one incidental cyst.'], [['No history','Disease still possible'],['Imaging','Must fit'],['Genetics','Useful in selected cases']], [PK,GP])
q('What does the Mayo Imaging Classification primarily use for typical ADPKD?', 'Age and height-adjusted total kidney volume',[
 ('Serum sodium alone','This does not provide the structural progression classification.'),('Number of liver cysts alone','The model concerns kidney volume and age.'),('Any atypical unilateral cystic pattern without qualification','The standard prognostic subclasses apply to typical class 1 morphology.')],
 'Structural burden can reveal risk before eGFR falls', '**MIC stratifies typical cystic disease into progression-risk subclasses.**', ['Atypical morphology needs a different interpretation.','Borderline 1C requires clinical judgment and additional risk evidence.'], '**Combine imaging with trajectory and other factors.**', ['Historical eGFR slope and genotype can add information.','Do not use one category without confirming applicability.'], [['Inputs','Age and htTKV'],['Scope','Typical morphology'],['Borderline 1C','Additional assessment']], [PK])
q('Which adult ADPKD patient most clearly warrants discussion of tolvaptan under KDIGO 2025?', 'A patient with eGFR at least 25 and evidence of rapid progression, after contraindication and burden assessment',[
 ('Every patient with one simple kidney cyst','This is not ADPKD treatment eligibility.'),('Every elderly stable slow-progressor regardless of burden','Expected benefit and context matter.'),('A patient with active significant liver disease without review','Hepatic contraindications and safety requirements are crucial.')],
 'Disease modification is targeted to progression risk', '**KDIGO recommends tolvaptan in suitable adults at risk of rapid progression.**', ['MIC, eGFR decline and other evidence guide the decision.','Age and competing causes of decline require interpretation.'], '**Use shared decision-making.**', ['Aquaresis and monitoring can be burdensome.','Review access, pregnancy and liver-related precautions.'], [['Function','eGFR at least 25'],['Risk','Rapid progression'],['Suitability','Safety and patient priorities']], [PK])
q('What is tolvaptan’s relevant mechanism in ADPKD?', 'Vasopressin V2-receptor antagonism',[
 ('Direct blockade of the angiotensin II AT1 receptor','That is a different antihypertensive mechanism.'),('Inhibition of acetylcholinesterase','This is unrelated to cystic disease modification.'),('Direct destruction of all cyst epithelium','It does not eradicate established cysts.')],
 'Vasopressin signaling contributes to cyst biology', '**V2 antagonism reduces downstream signaling and causes aquaresis.**', ['Thirst, polyuria and nocturia are expected practical issues.','The aim is slower progression rather than immediate restoration of kidney architecture.'], '**Protect hydration and safe use.**', ['Provide illness-related interruption instructions.','Reassess tolerance and benefit over time.'], [['Target','V2 receptor'],['Expected effect','Aquaresis'],['Goal','Slow progression']], [PK])
q('Which monitoring issue is particularly important during tolvaptan treatment for ADPKD?', 'Protocol-based liver testing and prompt assessment of symptoms suggesting liver injury',[
 ('No liver testing after a normal baseline','Ongoing monitoring is required.'),('Aquaresis is the only possible adverse effect','Hepatic injury is an important risk.'),('A lower protein dipstick eliminates hepatotoxicity risk','That is not a safety marker.')],
 'A progression benefit must be balanced against preventable toxicity', '**Use the current product- and jurisdiction-specific liver-monitoring schedule.**', ['Review fatigue, anorexia, dark urine or jaundice promptly.','Assess interacting drugs and contraindications.'], '**Teach safe interruption and contact rules.**', ['Illness with limited water access can create dehydration risk.','Do not restart suspected hepatic injury without appropriate review.'], [['Liver','Scheduled and symptom-triggered review'],['Water balance','Aquaresis precautions'],['Follow-up','Product-specific']], [PK])
q('ADPKD is accompanied by persistent fever, focal renal pain and inflammatory markers; routine urine culture is negative. What must be considered?', 'Infected renal cyst',[
 ('A negative urine culture excludes cyst infection','An infected cyst may not communicate with the collecting system.'),('Every painful cyst is infected','Hemorrhage and stones are alternatives.'),('Immediate elective nephrectomy is mandatory for all cases','Imaging and medical/source-control decisions are individualized.')],
 'A closed compartment can produce a negative urine test', '**Cyst infection can be difficult to distinguish from hemorrhage.**', ['Blood cultures and suitable imaging can help.','FDG-PET may be useful in selected uncertain cases.'], '**Choose therapy with cyst penetration and resistance in mind.**', ['Persistent infection may need drainage or other source control.','Coordinate renal and infectious-disease care.'], [['Urine culture','Can be negative'],['Differential','Hemorrhage/stone/infection'],['Treatment','Penetration and source control']], [PK], 'clinical_scenario')
q('An ADPKD patient develops gross hematuria and flank pain but is stable and afebrile. What is the best principle?', 'Assess cyst hemorrhage, stones and other causes, using conservative care when appropriate and investigating persistent or atypical bleeding',[
 ('Every episode requires antibiotics','Infection is not established by blood alone.'),('All bleeding can permanently be attributed to cysts without reassessment','Malignancy and other causes remain possible.'),('Immediate nephrectomy is routine for a first mild episode','Most cases do not require that intervention.')],
 'A common cyst complication still has a differential', '**Cyst bleeding can cause transient macroscopic hematuria.**', ['Check hemodynamic status, pain and clot/obstruction risks.','Persistent or recurrent atypical bleeding merits further evaluation.'], '**Balance hydration advice with the renal and cardiac state.**', ['Avoid harmful analgesic exposure.','Seek urgent care for instability, obstruction or severe infection signs.'], [['Stable bleeding','Often conservative assessment'],['Red flags','Instability/obstruction/infection'],['Persistence','Broaden work-up']], [PK], 'clinical_scenario')
q('Which ADPKD context particularly supports intracranial aneurysm screening discussion?', 'Personal SAH or a relevant family history of aneurysm, SAH or unexplained sudden death, with broader individualized shared decision-making',[
 ('Every screening decision is determined by eGFR alone','Risk extends beyond filtration.'),('A negative family history makes all aneurysm assessment inappropriate','Other contexts and patient preferences can matter.'),('Screening is performed by routine LP','Noninvasive vascular imaging is used.')],
 'Extrarenal vascular risk needs a targeted approach', '**KDIGO emphasizes risk history and informed discussion.**', ['Noncontrast time-of-flight MRA is a common screening method.','High-risk occupations or major clinical decisions can add context.'], '**Distinguish screening from a symptomatic emergency.**', ['Thunderclap headache needs urgent acute evaluation.','A negative prior screen does not make every future severe headache benign.'], [['Screening','Risk-informed'],['Imaging','Usually noninvasive vascular assessment'],['Thunderclap','Emergency pathway']], [PK])
q('What is the usual implication of liver cysts in ADPKD?', 'They are a common extrarenal manifestation, with treatment driven by symptoms and complications rather than cyst presence alone',[
 ('They invariably cause cirrhosis and liver failure','Most do not.'),('Every cyst needs aspiration','Routine intervention is not indicated.'),('They exclude the ADPKD diagnosis','They support the systemic phenotype.')],
 'An imaging manifestation is not automatically an intervention target', '**Polycystic liver burden can cause pain, fullness or compression in selected patients.**', ['Infection and bleeding are complications requiring specific care.','Kidney and liver burden do not necessarily progress identically.'], '**Use a symptom-directed specialist plan.**', ['Options differ for focal dominant cysts and diffuse severe disease.','Avoid unnecessary procedures for incidental asymptomatic lesions.'], [['Asymptomatic cysts','Usually observe'],['Symptoms','Assess burden and alternatives'],['Complications','Targeted management']], [PK,GP])
q('A long-term dialysis patient develops multiple cysts in previously small kidneys without a dominant family history. Which diagnosis is favored?', 'Acquired cystic kidney disease',[
 ('ADPKD proven by cyst number alone','ACKD occurs with advanced CKD and has a different background phenotype.'),('Simple childhood congenital hydronephrosis','This does not fit the acquired cystic course.'),('MCD','This does not cause this imaging pattern.')],
 'Cysts can arise as a consequence of chronic kidney disease', '**ACKD becomes more common with prolonged kidney failure and dialysis exposure.**', ['Hemorrhage and renal tumors are important complications.','Kidneys are not typically enlarged in the same inherited pattern.'], '**Evaluate new hematuria or mass symptoms.**', ['Use the appropriate renal cancer assessment pathway.','Do not label all cystic kidneys hereditary.'], [['Context','Advanced CKD/dialysis'],['Kidney size','Often small or not markedly enlarged'],['Complications','Bleeding/tumors']], [AC], 'clinical_scenario')
q('One thin-walled simple renal cyst is found incidentally in an older adult with normal renal anatomy otherwise. What is the best interpretation?', 'An isolated simple cyst does not establish ADPKD',[
 ('Every cyst proves inherited polycystic disease','Incidental simple cysts are common.'),('A simple cyst always requires nephrectomy','That is inappropriate.'),('Any cyst is automatically malignant','Complexity and imaging features determine concern.')],
 'Interpret cyst morphology and distribution', '**Simple and complex cystic lesions have different assessment pathways.**', ['Age and family context matter.','Suspicious complexity needs a dedicated radiological evaluation.'], '**Avoid unnecessary hereditary labeling.**', ['Review the complete scan rather than the word cyst alone.','Use targeted follow-up only when clinically indicated.'], [['Single simple cyst','Often incidental'],['Diffuse bilateral disease','Different diagnostic context'],['Complex lesion','Dedicated characterization']], [PK,AC])

if __name__=='__main__':finalize('Nephrology',5,'Tubulointerstitial and Cystic Kidney Disease','neph-tubulointerstitial-cystic',rows,28)
